sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        return; 
    }
    if (newValue === '') {
        return; 
    }

    var currentStateValue = g_form.getValue('state');


    g_form.clearOptions('state');

    if (newValue === 'amend') {
        g_form.addOption('state', 'ready_rpa', 'Amend - Ready to be sent');
        g_form.addOption('state', 'error_rpa', 'Amend - Error');
        g_form.addOption('state', 'processing_rpa', 'Amend - Processing');
        g_form.addOption('state', 'processed_rpa', 'Amend - Processed');
    } else {
        g_form.addOption('state', 'ready_ghss', 'Ready to be sent');
        g_form.addOption('state', 'error_ghss', 'Error');
        g_form.addOption('state', 'processing_ghss', 'Processing');
        g_form.addOption('state', 'processed_ghss', 'Processed');
    }

    if (g_form.getOption('state', currentStateValue)) {
        g_form.setValue('state', currentStateValue);
    } else {
        g_form.setValue('state', '');
    }
}
